import{St as e,at as t,it as n,n as r,st as i,tt as a,vt as o}from"./chunks/framework.BPeR9Rpo.js";var s=JSON.parse(`{"title":"Solutions","description":"","frontmatter":{"title":"Solutions","covers":{"screens":["SCR-060","SCR-061"],"stories":["US-038","US-039"]}},"headers":[],"relativePath":"usage/solutions.md","filePath":"usage/solutions.md"}`),c={name:`usage/solutions.md`};function l(r,s,c,l,u,d){let f=e(`Screenshot`);return o(),n(`div`,null,[s[0]||=t(`<h1 id="solutions" tabindex="-1">Solutions <a class="header-anchor" href="#solutions" aria-label="Permalink to “Solutions”">​</a></h1><p>A solution is the container of a change initiative, such as a new module, a replaced interface or a platform migration. It states in its <strong>architecture vision</strong> what the initiative wants to achieve and what it covers, so that everyone involved has the same picture. Later the solution also holds the planned changes to the landscape.</p><p>You need the permission <code>entity:read</code> (for example the role <code>viewer</code>) to see solutions. To create one, you need <code>solution:write</code>: the roles <code>solution-architect</code> and <code>enterprise-architect</code> hold it (see <a href="./../administration/roles-and-permissions">Roles and permissions</a>).</p><h2 id="create-a-solution" tabindex="-1">Create a solution <a class="header-anchor" href="#create-a-solution" aria-label="Permalink to “Create a solution”">​</a></h2><ol><li><p>Choose <em>Solutions</em> in the header, then <em>New solution</em>.</p></li><li><p>Fill in the dialog <em>New solution</em>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>Name</td><td>required, up to 255 characters; unique within the instance, regardless of upper and lower case and of spaces at the start and end</td></tr><tr><td>Architecture vision</td><td>optional, up to 2000 characters: the goal, the scope and the rationale of the initiative. Line breaks are kept</td></tr></tbody></table></li></ol>`,5),i(f,{name:`solution-create`,alt:`Dialog New solution with name and architecture vision`}),s[1]||=t(`<ol start="3"><li>Choose <em>Create solution</em>. The page of the new solution opens.</li></ol><p>If the name is already taken, the dialog says so, for example &quot;Name &#39;ERP Extension Logistics&#39; is already taken&quot;; choose another name. Without <code>solution:write</code>, you see the solutions but not <em>New solution</em>.</p><p>A new solution has the status <em>Draft</em>, and you are its owner. It is created in <strong>project mode</strong>: without a baseline and target plateau. Plateau mode follows with the plateaus.</p><h2 id="view-solutions" tabindex="-1">View solutions <a class="header-anchor" href="#view-solutions" aria-label="Permalink to “View solutions”">​</a></h2><p>The page <em>Solutions</em> lists every solution with its status, owner and creation date, ordered by name:</p>`,5),i(f,{name:`solutions`,alt:`List of solutions`}),s[2]||=a(`p`,null,`Open a solution to see its architecture vision and its baseline:`,-1),i(f,{name:`solution`,alt:`Page of a solution with owner, creation time, architecture vision and baseline`}),s[3]||=t(`<p>Solutions cannot be changed or archived yet.</p><h2 id="baseline" tabindex="-1">Baseline <a class="header-anchor" href="#baseline" aria-label="Permalink to “Baseline”">​</a></h2><p>The area <em>Baseline</em> of a solution shows the current IT landscape the initiative builds on: every entity in the catalog today that is not deleted, with its name and metatype, ordered by name. Connections such as data flows are not listed. The baseline is read when you open the solution, so it always shows the catalog as it is now.</p><ul><li><strong>Search:</strong> type a part of the name, up to 255 characters; upper and lower case do not matter.</li><li><strong>Filter:</strong> choose a metatype to see only its entities.</li><li><strong>Pages:</strong> the baseline shows 50 entities per page.</li></ul><p>If the catalog holds no entities yet, the area says &quot;No entities in the current landscape – you can only create new entities&quot;. If only your search or filter matches nothing, it says so instead.</p><h2 id="through-the-api" tabindex="-1">Through the API <a class="header-anchor" href="#through-the-api" aria-label="Permalink to “Through the API”">​</a></h2><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;name&quot;: &quot;ERP Extension Logistics&quot;, &quot;description&quot;: &quot;Goal: warehouse logistics in the ERP.&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/solutions&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/solutions&quot;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># $SOLUTION is the &quot;id&quot; of a solution from the list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/solutions/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SOLUTION</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/landscape?q=erp&amp;pageSize=50&quot;</span></span></code></pre></div><p><code>POST /solutions</code> answers 201 with the solution, 422 naming <code>name</code> for a blank or taken name, and 403 without <code>solution:write</code>. Every creation is recorded in the audit log as <code>solution.created</code>.</p><p><code>GET /solutions/{id}/landscape</code> answers one page of the baseline with the total and, if a further page exists, a <code>nextCursor</code>; send it as <code>cursor</code> together with <code>page</code> + 1 to load the next page. <code>metatypeId</code> filters by metatype.</p>`,9)])}var u=r(c,[[`render`,l]]);export{s as __pageData,u as default};